export declare const reportStyles = "\n:root {\n  color-scheme: light;\n  --bg: #f8fafc;\n  --panel: #ffffff;\n  --ink: #0f172a;\n  --muted: #64748b;\n  --line: #d9e2ec;\n  --blue: #1769e0;\n  --blue-dark: #0f3f8f;\n  --green: #18794e;\n  --yellow: #a16207;\n  --red: #b42318;\n  --shadow: 0 18px 50px rgba(15, 23, 42, 0.12);\n}\n* {\n  box-sizing: border-box;\n}\nbody {\n  margin: 0;\n  background: var(--bg);\n  color: var(--ink);\n  font: 14px/1.5 ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n}\nheader {\n  background: #08111f;\n  color: #ffffff;\n  padding: 44px 32px 36px;\n}\n.wrap {\n  max-width: 1180px;\n  margin: 0 auto;\n}\n.eyebrow {\n  color: #9ec5ff;\n  font-size: 13px;\n  font-weight: 700;\n  letter-spacing: 0;\n  text-transform: uppercase;\n}\nh1 {\n  margin: 6px 0 8px;\n  font-size: 40px;\n  line-height: 1.08;\n  letter-spacing: 0;\n}\nh2 {\n  margin: 34px 0 14px;\n  font-size: 22px;\n  letter-spacing: 0;\n}\n.subtitle {\n  color: #dbeafe;\n  max-width: 760px;\n  font-size: 16px;\n}\n.meta {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 12px;\n  margin-top: 20px;\n}\n.pill {\n  border: 1px solid rgba(255, 255, 255, 0.22);\n  border-radius: 999px;\n  padding: 6px 10px;\n  color: #e0f2fe;\n}\nmain {\n  padding: 26px 32px 56px;\n}\n.grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));\n  gap: 14px;\n}\n.card {\n  background: var(--panel);\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  box-shadow: var(--shadow);\n  padding: 16px;\n}\n.metric {\n  color: var(--muted);\n  font-size: 12px;\n  text-transform: uppercase;\n  font-weight: 700;\n}\n.value {\n  font-size: 28px;\n  font-weight: 800;\n  margin-top: 4px;\n}\ntable {\n  width: 100%;\n  border-collapse: collapse;\n  background: var(--panel);\n  border: 1px solid var(--line);\n  border-radius: 8px;\n  overflow: hidden;\n}\nth, td {\n  padding: 11px 12px;\n  border-bottom: 1px solid var(--line);\n  text-align: left;\n  vertical-align: top;\n}\nth {\n  background: #edf4ff;\n  color: var(--blue-dark);\n  font-size: 12px;\n  text-transform: uppercase;\n}\ntr:last-child td {\n  border-bottom: 0;\n}\n.status {\n  display: inline-flex;\n  border-radius: 999px;\n  padding: 3px 8px;\n  font-weight: 700;\n  font-size: 12px;\n}\n.status.completed {\n  background: #dcfce7;\n  color: var(--green);\n}\n.status.test_failed,\n.status.agent_failed,\n.status.timed_out,\n.status.internal_error,\n.status.risk_blocked {\n  background: #fee2e2;\n  color: var(--red);\n}\n.status.no_changes {\n  background: #fef3c7;\n  color: var(--yellow);\n}\ndetails {\n  margin-top: 10px;\n}\nsummary {\n  cursor: pointer;\n  color: var(--blue);\n  font-weight: 700;\n}\npre {\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  background: #0b1220;\n  color: #e5edf7;\n  border-radius: 8px;\n  padding: 14px;\n  max-height: 420px;\n  overflow: auto;\n}\n.risk {\n  margin: 4px 0;\n}\n.muted {\n  color: var(--muted);\n}\n@media (max-width: 760px) {\n  header, main {\n    padding-left: 18px;\n    padding-right: 18px;\n  }\n  h1 {\n    font-size: 32px;\n  }\n  table {\n    display: block;\n    overflow-x: auto;\n  }\n}\n";
